pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    RevertingLog log;

    function setUp() public {
        c = new C();
        log = new RevertingLog();
    }

    function testFuzz_property(uint256 lockTime, uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0);
        c.SetLogFile(address(log));
        c.Initialized();
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount, gas: 200000}(
            abi.encodeWithSelector(c.Put.selector, lockTime)
        );
        // Rule: once a LogFile is configured, Put must succeed only if the log
        // accepts the message; with a reverting log, Put must revert for EVERY input.
        assertTrue(!ok);
    }
}

contract RevertingLog {
    fallback() external payable {
        revert();
    }
}

