pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    SpyLog log;

    function setUp() public {
        c = new C();
        log = new SpyLog();
        c.SetLogFile(address(log));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(log) && actor != address(this));
        vm.assume(amount > 0 && amount % 2 == 0); // admissible even deposits, wide domain
        vm.assume(amount < type(uint256).max - 1);
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(0) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: any even deposit via Put always succeeds (never reverts).
        // The mutant logs amount+1 (odd), the logging counterparty rejects it and Put reverts.
        assertTrue(ok);
    }
}

// Adversarial counterparty: the log file C calls into; it accepts only
// even-valued log entries and reverts on odd ones.
contract SpyLog {
    function AddMessage(address, uint _val, string calldata) external pure {
        if (_val % 2 == 1) revert();
    }
}

