contract Log {
    struct Message {
        address Sender;
        string Data;
        uint256 Val;
        uint256 Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint256 _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    function HistoryLength() public view returns (uint256) {
        return History.length;
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function check(uint _val) public {
        c.SetLogFile(address(this));
        c.SetMinSum(_val);
        assert(c.MinSum() == _val);
    }

    receive() external payable {}
    fallback() external payable {}
}

